 const ev=(e,i)=>`<li><button class="ev" type="button" data-act="acc" data-id="ev${i}" aria-expanded="${S.open['ev'+i]?'true':'false'}" aria-controls="acc-ev${i}"><span class="tm">${fdt(e.at)}</span><span><b style="font-weight:500">${esc(e.where)}</b> · ${esc(e.what)}</span><span class="chev" aria-hidden="true">${IC.chv}</span></button><div class="acc-b ev-b" id="acc-ev${i}" ${S.open['ev'+i]?'':'hidden'}>${esc(e.detail_policy||'')}${e.where.startsWith('DS1')?' · у клиентов: «обновление данных рынка не удалось», данные на 30.09 18:05 · лимит исследователя исчерпан до 03.10 09:00 — что станет с заданиями клиентов, не определено':''}</div></li>`;
